import csv
import io
import re
from typing import List, Dict, Any


def parse_csv(raw_csv: str) -> Dict[str, Any]:
    expected_width = 8

    try:
        records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"'))
    except csv.Error:
        records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"', strict=False))

    if not records:
        return {"columns": [], "rows": []}

    if records[0]:
        records[0][0] = records[0][0].lstrip("\ufeff")

    nonblank = [(i, row) for i, row in enumerate(records) if any(value.strip() for value in row)]
    if not nonblank:
        return {"columns": [], "rows": []}

    header_index = None
    for i, row in nonblank:
        populated = sum(bool(value.strip()) for value in row)
        if len(row) >= expected_width - 1 and populated >= expected_width - 1:
            header_index = i
            break

    if header_index is None:
        header_index = nonblank[0][0]

    header = list(records[header_index])
    width = max(expected_width, len(header))
    header.extend([""] * (width - len(header)))

    data_records = []
    for row in records[header_index + 1:]:
        if not any(value.strip() for value in row):
            continue
        data_records.append(list(row))
        width = max(width, len(row))

    if width > len(header):
        header.extend("Extra {}".format(i + 1) for i in range(width - len(header)))

    rows = []
    for row in data_records:
        row.extend([""] * (width - len(row)))
        rows.append(row)

    return {"columns": header, "rows": rows}
